[{"order":1,"type":"heading","text":"Understanding Directives in GraphQL: Built-in and Custom"},{"order":2,"type":"paragraph","text":"Directives are a powerful feature in GraphQL that allow you to attach behavior, metadata, or conditional logic to your queries, mutations, schemas, and types. They are prefixed with the @ symbol and can change how a server executes a query or how a client interprets data."},{"order":3,"type":"subheading","text":"Built-in Directives"},{"order":4,"type":"paragraph","text":"GraphQL specification defines standard built-in directives that are supported by almost all compliant servers. The two most common are @include and @skip."},{"order":5,"type":"bullet_point","text":"@include(if: Boolean): Includes the targeted field or fragment only if the 'if' argument evaluates to true."},{"order":6,"type":"bullet_point","text":"@skip(if: Boolean): Skips the targeted field or fragment if the 'if' argument evaluates to true."},{"order":7,"type":"code","text":"query GetUser($withEmail: Boolean!) {
  user(id: "1") {
    name
    email @include(if: $withEmail)
    phone @skip(if: $withEmail)
  }
}"},{"order":8,"type":"subheading","text":"Custom Directives"},{"order":9,"type":"paragraph","text":"Beyond the built-in directives, GraphQL allows developers to define custom directives in the type system definition language (SDL). Custom directives are useful for access control, data masking, formatting, or internationalization."},{"order":10,"type":"code","text":"directive @auth(requires: Role = USER) on FIELD_DEFINITION | OBJECT

enum Role {
  ADMIN
  USER
  GUEST
}

type User @auth(requires: ADMIN) {
  id: ID!
  salary: Float @auth(requires: ADMIN)
  profile: String
}"},{"order":11,"type":"subheading","text":"Implementing Custom Directives on the Server"},{"order":12,"type":"paragraph","text":"To implement custom directives, GraphQL server libraries (like Apollo Server or Yoga) provide schema transformation tools or directive visitors that intercept field resolution based on the presence of the directive."},{"order":13,"type":"code","text":"const { mapSchema, getDirective, MapperKind } = require("@graphql-tools/utils");

function authDirectiveTransformer(schema, directiveName) {
  return mapSchema(schema, {
    [MapperKind.FIELD_DEFINITION]: (fieldConfig) => {
      const authDirective = getDirective(schema, fieldConfig, directiveName)?.[0];
      if (authDirective) {
        const { resolve = defaultFieldResolver } = fieldConfig;
        const requiredRole = authDirective.requires;
        fieldConfig.resolve = async function (source, args, context, info) {
          if (!context.user || context.user.role !== requiredRole) {
            throw new Error("Unauthorized access");
          }
          return resolve(source, args, context, info);
        };
      }
      return fieldConfig;
    },
  });
}"},{"order":14,"type":"subheading","text":"Conclusion"},{"order":15,"type":"paragraph","text":"Directives bridge the gap between static schemas and dynamic execution. By leveraging built-in directives for query optimization and custom directives for cross-cutting concerns like authorization and validation, you can build modular and secure GraphQL APIs."}]
